<?php require 'config.php';require_role('admin');check_csrf();$tab=$_GET['tab']??'org';
if($_SERVER['REQUEST_METHOD']==='POST'){
if(isset($_POST['verify_org'])){db()->prepare('UPDATE organizations SET status_verifikasi=? WHERE user_id=?')->execute([$_POST['verify_org'],(int)$_POST['id']]);flash('success','Status organisasi diperbarui.');}
if(isset($_POST['moderate'])){db()->prepare('UPDATE events SET status=? WHERE kegiatan_id=?')->execute([$_POST['moderate'],(int)$_POST['id']]);flash('success','Status kegiatan diperbarui.');}
if(isset($_POST['delete_user'])){db()->prepare("DELETE FROM users WHERE user_id=? AND role<>'admin'")->execute([(int)$_POST['id']]);flash('success','Pengguna dihapus.');}
redirect('admin.php?tab='.urlencode($tab));
}
layout_start('Administrasi');?><div class="page-heading"><span class="eyebrow">ADMINISTRATOR</span><h1>Administrasi platform</h1><p class="muted">Verifikasi organisasi, moderasi kegiatan, dan pengelolaan pengguna.</p></div><div class="tabs"><a class="<?=$tab==='org'?'active':''?>" href="?tab=org">Organisasi</a><a class="<?=$tab==='events'?'active':''?>" href="?tab=events">Moderasi kegiatan</a><a class="<?=$tab==='users'?'active':''?>" href="?tab=users">Pengguna</a></div><?php if($tab==='org'){$rows=db()->query("SELECT o.*,u.nama,u.email FROM organizations o JOIN users u ON u.user_id=o.user_id ORDER BY o.status_verifikasi='Menunggu' DESC")->fetchAll();?><div class="table-wrap"><table><tr><th>Organisasi</th><th>Penanggung jawab</th><th>Alamat</th><th>Status</th><th>Aksi</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['nama_organisasi'])?></td><td><?=e($r['nama'])?><br><small><?=e($r['email'])?></small></td><td><?=e($r['alamat'])?></td><td><?=badge($r['status_verifikasi'])?></td><td><form class="inline-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['user_id']?>"><button class="btn btn-primary small" name="verify_org" value="Terverifikasi">Verifikasi</button><button class="btn btn-outline small" name="verify_org" value="Ditolak">Tolak</button></form></td></tr><?php endforeach;?></table></div><?php }elseif($tab==='events'){$rows=db()->query("SELECT e.*,o.nama_organisasi FROM events e JOIN organizations o ON o.user_id=e.organisasi_id ORDER BY e.created_at DESC")->fetchAll();?><div class="table-wrap"><table><tr><th>Kegiatan</th><th>Organisasi</th><th>Tanggal</th><th>Status</th><th>Aksi</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['nama_kegiatan'])?></td><td><?=e($r['nama_organisasi'])?></td><td><?=date('d M Y',strtotime($r['tanggal']))?></td><td><?=badge($r['status'])?></td><td><form class="inline-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['kegiatan_id']?>"><button class="btn btn-primary small" name="moderate" value="Dipublikasikan">Publikasikan</button><button class="btn btn-outline small" name="moderate" value="Ditangguhkan">Tangguhkan</button></form></td></tr><?php endforeach;?></table></div><?php }else{$rows=db()->query("SELECT * FROM users ORDER BY created_at DESC")->fetchAll();?><div class="table-wrap"><table><tr><th>Nama</th><th>Email</th><th>Role</th><th>Terdaftar</th><th>Aksi</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['nama'])?></td><td><?=e($r['email'])?></td><td><?=e($r['role'])?></td><td><?=date('d M Y',strtotime($r['created_at']))?></td><td><?php if($r['role']!=='admin'):?><form method="post" onsubmit="return confirm('Hapus pengguna ini?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['user_id']?>"><button class="btn btn-outline small" name="delete_user" value="1">Hapus</button></form><?php endif;?></td></tr><?php endforeach;?></table></div><?php } layout_end(); ?>